insert into public.football_team_profiles (team_id, nickname, tags, intro) values
(4, '슈바르츠겔벤', '{도르트문트,지그날 이두나 파크,1909년 창단}', $t$<p>보루시아 도르트문트는 독일 서부 루르 지방의 공업 도시 도르트문트를 대표하는 구단입니다. 홈구장 남쪽 스탠드를 가득 메우는 2만 명 넘는 입석 관중 "노란 벽(Die Gelbe Wand)"은 세계에서 가장 유명한 응원석 가운데 하나입니다. 1997년 챔피언스리그 우승을 차지했고, 2013년과 2024년에도 결승에 올랐습니다. 이웃 샬케와의 레비어 더비는 독일에서 가장 뜨거운 라이벌전입니다.</p><p>토리코리 관전 포인트: 도르트문트는 젊은 유망주를 키워 비싸게 파는 구단으로도 유명합니다. 핵심 선수가 자주 바뀌는 만큼 시즌 초반 폼이 들쑥날쑥한 경우가 많아, 최근 5경기 흐름과 홈 성적을 함께 보는 것이 좋습니다.</p>$t$),
(5, '로텐', '{뮌헨,알리안츠 아레나,1900년 창단}', $t$<p>바이에른 뮌헨은 독일 최다 우승 구단으로, 2012-13 시즌부터 11시즌 연속 분데스리가 우승이라는 기록을 세웠습니다. 챔피언스리그(유러피언컵)를 여섯 번 우승했고, 2013년과 2020년에는 트레블을 달성했습니다. 회원 수가 수십만 명에 이르는 세계 최대 규모의 회원제 구단 가운데 하나입니다.</p><p>토리코리 관전 포인트: 바이에른은 거의 모든 경기에서 우세를 점하기 때문에 승점보다 골득실과 실점을 보는 편이 흐름을 읽기 좋습니다. 경기당 실점이 1골을 넘는 시즌에는 우승 경쟁이 뜻밖에 치열해지곤 했습니다.</p>$t$),
(17, '브라이스가우어', '{프라이부르크,오이로파파크 슈타디온,1904년 창단}', $t$<p>SC 프라이부르크는 독일 남서부 슈바르츠발트(검은 숲) 지방의 대학 도시를 연고로 하는 구단입니다. 크리스티안 슈트라이히 감독이 2011년부터 2024년까지 13년 가까이 팀을 이끌며 적은 예산으로 꾸준히 유럽대항전에 도전하는 팀을 만들었습니다. 2021년 새 경기장으로 옮겼습니다.</p><p>토리코리 관전 포인트: 프라이부르크는 스타 선수보다 조직력으로 승부하는 팀입니다. 경기당 실점이 낮고 무승부가 적당히 섞이는 "지지 않는 축구"를 할 때 성적이 좋았으니, 패배 수를 먼저 확인해 보세요.</p>$t$),
(16, '푸거슈테터', '{아우크스부르크,WWK 아레나,1907년 창단}', $t$<p>FC 아우크스부르크는 독일 남부 바이에른주의 역사 도시 아우크스부르크를 연고로 합니다. 2011년 처음 분데스리가에 오른 뒤 꾸준히 1부 리그에 머물고 있으며, 지동원과 구자철 등 한국 선수들이 활약해 한국 팬들에게도 친숙한 구단입니다.</p><p>토리코리 관전 포인트: 아우크스부르크는 늘 강등권과 중위권 사이에서 싸우는 팀입니다. 홈에서 승점을 얼마나 챙기는지가 한 시즌의 성패를 가르기 때문에, 홈 경기당 승점이 1.5를 넘는지 확인해 보면 좋습니다.</p>$t$),
(3, '베르크셀프', '{레버쿠젠,바이아레나,1904년 창단}', $t$<p>바이어 04 레버쿠젠은 제약회사 바이엘의 노동자 스포츠 클럽에서 출발한 구단으로, 기업 구단이라 50+1 규정의 예외를 인정받고 있습니다. 준우승을 유독 많이 해 "네버쿠젠"이라는 별명까지 얻었지만, 2023-24 시즌 분데스리가를 한 경기도 지지 않고 우승하고 DFB 포칼까지 들어 올리며 그 꼬리표를 떼어냈습니다. 손흥민이 2013년부터 2015년까지 활약한 팀이기도 합니다.</p><p>토리코리 관전 포인트: 레버쿠젠은 경기 막판 골이 많은 팀으로 알려져 있습니다. 후반 득점과 역전 승점을 보면 끝까지 몰아붙이는 팀의 성향이 잘 드러납니다.</p>$t$),
(15, '눌퓐퍼', '{마인츠,MEWA 아레나,1905년 창단}', $t$<p>1. FSV 마인츠 05는 독일 서부 라인강변의 도시 마인츠를 연고로 합니다. 위르겐 클롭과 토마스 투헬이 지도자 경력을 시작한 곳으로 유명하며, 두 감독이 이후 세계적인 명장이 되면서 "명장의 요람"이라는 평가를 받습니다. 카니발 축제로 유명한 도시답게 홈 경기 분위기가 흥겹기로 이름났고, 이재성이 활약하며 한국 팬들에게도 친숙해졌습니다.</p><p>토리코리 관전 포인트: 마인츠는 강한 압박과 많은 활동량으로 상대를 괴롭히는 팀입니다. 이런 팀은 강팀을 상대로도 이변을 자주 만들어 내니, 라운드 리뷰의 "이변" 항목에 마인츠가 얼마나 등장하는지 지켜보세요.</p>$t$),
(719, 'SVE', '{슈피젠엘버스베르크,자를란트,1907년 창단}', $t$<p>SV 07 엘버스베르크는 독일 서남부 자를란트주의 인구 1만여 명 남짓한 작은 마을을 연고로 하는 구단입니다. 오랫동안 하부리그에 머물렀지만 2020년대 들어 연이은 승격으로 빠르게 올라와 독일 축구에서 가장 놀라운 성장 스토리 가운데 하나를 쓰고 있습니다.</p><p>토리코리 관전 포인트: 작은 구단이 분데스리가에서 살아남으려면 홈 경기장을 "원정팀의 무덤"으로 만들어야 합니다. 홈 무실점 경기와 원정 무득점 경기 수를 비교하면 엘버스베르크가 1부 무대에 어떻게 적응하고 있는지 알 수 있습니다.</p>$t$),
(12, '베르더', '{브레멘,베저슈타디온,1899년 창단}', $t$<p>SV 베르더 브레멘은 독일 북부 항구 도시 브레멘의 구단으로, 분데스리가를 네 번 우승했습니다. 2003-04 시즌에는 리그와 DFB 포칼을 함께 차지하는 더블을 달성했습니다. 함부르크와 치르는 "북부 더비"는 독일 북부 축구의 자존심이 걸린 경기입니다.</p><p>토리코리 관전 포인트: 베르더는 전통적으로 공격적인 축구를 선호해 득점과 실점이 모두 많은 시즌이 잦습니다. 2.5골 오버 비율이 리그 평균보다 높은지 확인하면 이번 시즌 베르더의 성향을 알 수 있습니다.</p>$t$),
(721, '로텐 불렌', '{라이프치히,레드불 아레나,2009년 창단}', $t$<p>RB 라이프치히는 음료 회사 레드불이 2009년 5부 리그 구단의 참가권을 사들여 만든 구단입니다. 창단 7년 만인 2016년 분데스리가에 올랐고, 곧바로 챔피언스리그 단골 팀이 됐습니다. 50+1 규정을 사실상 우회했다는 비판 속에서도 2022년과 2023년 DFB 포칼을 연달아 우승했습니다.</p><p>토리코리 관전 포인트: 라이프치히는 젊은 선수 중심의 빠른 압박과 역습이 특징입니다. 전반과 후반 득점 비율, 그리고 역습에 강한 팀과의 경기 결과를 함께 보면 팀의 현재 완성도를 가늠할 수 있습니다.</p>$t$),
(19, '아들러', '{프랑크푸르트,도이체방크 파크,1899년 창단}', $t$<p>아인트라흐트 프랑크푸르트는 독일 금융 중심지 프랑크푸르트를 연고로 하며, "아들러(독수리)"라는 별명을 갖고 있습니다. 1980년 UEFA컵 우승 당시 차범근이 주축으로 활약해 한국 팬들에게 특별한 의미가 있는 구단입니다. 2022년에는 유로파리그 결승에서 레인저스를 꺾고 42년 만에 유럽 정상에 다시 올랐습니다.</p><p>토리코리 관전 포인트: 프랑크푸르트는 유럽대항전 원정길에 수만 명의 팬이 따라가는 것으로 유명합니다. 유럽대항전을 병행하는 시즌에는 리그 원정 성적이 흔들리지 않는지 함께 살펴보세요.</p>$t$),
(6, '쾨니히스블라우엔', '{겔젠키르헨,펠틴스 아레나,1904년 창단}', $t$<p>FC 샬케 04는 루르 지방의 광산 도시 겔젠키르헨을 대표하는 구단으로, 분데스리가 출범 이전 독일 챔피언에 일곱 번 올랐습니다. 1997년 UEFA컵 우승을 차지했지만, 2020년대 들어 두 차례 강등되는 어려운 시기를 겪었습니다. 도르트문트와의 레비어 더비는 광산 노동자들의 자존심 대결에서 시작된 역사 깊은 라이벌전입니다.</p><p>토리코리 관전 포인트: 샬케처럼 팬층이 두터운 전통 구단은 홈 관중의 힘이 성적에 그대로 드러납니다. 6만 관중이 들어차는 펠틴스 아레나에서의 홈 경기당 승점이 잔류와 도약의 기준이 됩니다.</p>$t$),
(29, '파더보르너', '{파더보른,벤텔러 아레나,1985년 창단}', $t$<p>SC 파더보른 07은 독일 서부 노르트라인베스트팔렌주의 도시 파더보른을 연고로 하는 구단입니다. 2014-15 시즌 처음 분데스리가에 올라 개막 직후 한때 선두에 오르며 화제가 됐고, 2019-20 시즌에도 1부를 경험했습니다. 작은 예산으로 승격을 여러 차례 이뤄 낸 "엘리베이터 구단"입니다.</p><p>토리코리 관전 포인트: 파더보른은 1부에 오를 때마다 공격적인 축구로 주목받았지만 실점이 많아 고전했습니다. 경기당 실점이 2골 가까이 되는지 여부가 이번 시즌 잔류 가능성을 보여주는 첫 번째 신호입니다.</p>$t$),
(1, '에페체', '{쾰른,라인에네르기 슈타디온,1948년 창단}', $t$<p>1. FC 쾰른은 1963-64 시즌 출범한 분데스리가의 초대 챔피언입니다. 구단의 상징인 염소 마스코트 "헤네스"가 홈 경기마다 경기장에 등장하는 것으로 유명합니다. 1부와 2부를 자주 오가는 팀이지만, 5만 명의 홈 관중이 늘 경기장을 채우는 열정적인 팬덤을 갖고 있습니다.</p><p>토리코리 관전 포인트: 승격과 강등을 반복해 온 팀은 강등권 경쟁 팀과의 맞대결이 사실상 "승점 6점짜리" 경기입니다. 하위권 팀 상대 결과와 홈 성적을 함께 보면 쾰른의 잔류 가능성이 보입니다.</p>$t$),
(2, 'TSG', '{진스하임,프리제로 아레나,1899년 창단}', $t$<p>TSG 1899 호펜하임은 인구 수천 명의 작은 마을 구단에서 출발했습니다. 소프트웨어 기업 SAP의 공동 창업자 디트마어 호프의 후원을 받아 하부리그에서 빠르게 올라와 2008년 분데스리가에 처음 입성했습니다. 젊은 지도자와 데이터 분석을 적극적으로 활용하는 구단으로 알려져 있습니다.</p><p>토리코리 관전 포인트: 호펜하임은 공격적인 운영으로 골이 많이 나는 경기가 잦습니다. 양팀 득점 비율이 높은 시즌에는 수비 안정이 순위를 끌어올릴 열쇠가 됩니다.</p>$t$),
(10, '슈바벤', '{슈투트가르트,MHP 아레나,1893년 창단}', $t$<p>VfB 슈투트가르트는 독일 남서부 자동차 산업 도시 슈투트가르트의 구단으로, 분데스리가를 다섯 번 우승했습니다. 2023년 승강 플레이오프 끝에 간신히 잔류한 뒤, 다음 시즌 곧바로 리그 2위에 오르는 극적인 반전을 이뤘고, 2025년에는 DFB 포칼을 우승했습니다.</p><p>토리코리 관전 포인트: 슈투트가르트처럼 한 시즌 만에 순위가 크게 바뀌는 팀은 기대득점 같은 과정 지표와 실제 성적의 차이가 큰 경우가 많습니다. 골득실과 승점이 함께 움직이는지 보면 흐름의 지속 가능성을 판단할 수 있습니다.</p>$t$),
(7, '디노', '{함부르크,폴크스파르크슈타디온,1887년 창단}', $t$<p>함부르크 SV는 분데스리가 출범 이후 한 번도 강등되지 않아 "공룡(디노)"이라고 불렸고, 경기장에는 1부 리그에 머문 시간을 세는 시계가 걸려 있었습니다. 1983년 유러피언컵 우승을 차지한 명문이지만 2018년 첫 강등을 겪은 뒤 오랫동안 2부에 머물렀습니다. 손흥민이 유소년 시절부터 프로 데뷔까지 성장한 구단이기도 합니다.</p><p>토리코리 관전 포인트: 오랜 2부 생활을 마친 전통 구단에게 가장 중요한 것은 시즌 초반 분위기입니다. 첫 10경기 경기당 승점이 1.2를 넘는지가 잔류 경쟁에서 여유를 가질 수 있는 기준입니다.</p>$t$),
(28, '아이제른', '{베를린,알테 푀르스테라이,1966년 창단}', $t$<p>1. FC 우니온 베를린은 옛 동독 시절 체제에 저항하는 팬들의 구단으로 알려진 베를린 동부의 팀입니다. 2008년 팬들이 직접 무보수로 홈구장 개보수 공사에 참여한 일화가 유명합니다. 2019년 처음 분데스리가에 오른 뒤 빠르게 성장해 2023-24 시즌 챔피언스리그 무대까지 밟았습니다.</p><p>토리코리 관전 포인트: 우니온은 입석 위주의 작은 경기장에서 뿜어내는 응원과 끈끈한 수비로 버티는 팀입니다. 무실점 경기 비율이 떨어지면 성적도 함께 떨어지는 경향이 뚜렷하니 수비 지표를 먼저 확인하세요.</p>$t$),
(18, '포흘렌', '{묀헨글라트바흐,보루시아 파크,1900년 창단}', $t$<p>보루시아 묀헨글라트바흐는 1970년대 분데스리가를 다섯 번 우승하고 UEFA컵을 두 번 들어 올린 독일 축구의 전통 강호입니다. 젊은 선수들이 빠르게 뛰어다니는 축구 때문에 "망아지(포흘렌)"라는 별명이 붙었습니다. 당시 바이에른 뮌헨과 치열한 라이벌 관계를 이루며 독일 축구의 황금기를 이끌었습니다.</p><p>토리코리 관전 포인트: 최근 글라트바흐는 중위권과 하위권을 오가며 재건 중입니다. 홈 경기와 원정 경기의 성적 차이가 크다면, 원정에서 승점을 쌓는 방법을 찾는 것이 반등의 열쇠입니다.</p>$t$)
